public partial class MainWindow : Window {
 readonly WindowCaptureService capture=new(); readonly OcrProcessService ocr=new(); readonly OverlayWindow overlay=new(); readonly CancellationTokenSource updateCheckCts=new(); CancellationTokenSource? operation; WindowInfo? current;
 readonly string root=AppContext.BaseDirectory, cacheDir, logDir, dataDir, diagnosticStatePath, planPath, rosterPath, objectivesPath, historyPath, learningProfilePath;
 const int HotkeyId=106, WmHotkey=0x0312;
 public MainWindow(){InitializeComponent();cacheDir=Path.Combine(root,"cache");logDir=Path.Combine(root,"logs");dataDir=Path.Combine(root,"data");diagnosticStatePath=Path.Combine(dataDir,"diagnostic-state.json");planPath=Path.Combine(dataDir,"show-plan.json");rosterPath=Path.Combine(dataDir,"roster.json");objectivesPath=Path.Combine(dataDir,"objectives.json");historyPath=Path.Combine(dataDir,"show-history.json");learningProfilePath=Path.Combine(dataDir,"learning-profile.json");Directory.CreateDirectory(cacheDir);Directory.CreateDirectory(logDir);Directory.CreateDirectory(dataDir);PreviewKeyDown+=OnKey;SourceInitialized+=RegisterInsertHotkey;Loaded+=async(_,_)=>await RefreshUpdateBadgeAsync();LoadLocalState();LoadActiveCareerUi();Append("V11.4.1 gestartet. Overlay aus. Keine automatische Erkennung aktiv.");}
 void LoadActiveCareerUi(){var profile=CareerProfileService.LoadActive(dataDir);if(profile is null)return;if(profile.Id=="ecw-s1"&&(profile.RosterRows.Any(x=>x.StartsWith("Kevin Owens")&&!x.Contains("| 0 | Jimmy Uso"))||profile.RosterRows.Any(x=>x.StartsWith("Cody Rhodes")&&!x.Contains("| 0 | Kevin Owens")))){var corrected=CareerProfileService.CurrentEcwCalibration();profile=corrected with{Week=profile.Week,UpdatedAt=DateTimeOffset.Now};CareerProfileService.SaveActive(dataDir,profile);File.WriteAllText(rosterPath,JsonSerializer.Serialize(new RosterSnapshot(profile.Brand,profile.Week,profile.RosterRows,profile.UpdatedAt),new JsonSerializerOptions{WriteIndented=true}));}CareerNameInput.Text=profile.Name;BrandInput.Text=profile.Brand;WeekInput.Text=profile.Week.ToString();RosterEditor.Text=string.Join(Environment.NewLine,profile.RosterRows);RosterStatus.Text=$"Aktiver Spielstand: {profile.Name} · {profile.RosterRows.Length} Superstars · {profile.MatchSlots} Matches · {profile.PromoSlots} Promos";}
 async Task RefreshUpdateBadgeAsync(){var result=await UpdateCheckService.CheckAsync(updateCheckCts.Token);if(result.Available){UpdatesButton.Content=$"● UPDATE {result.Latest} VERFÜGBAR";UpdatesButton.Background=new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(211,43,43));UpdatesButton.BorderBrush=System.Windows.Media.Brushes.White;UpdatesButton.ToolTip="Neue Version auf GitHub gefunden – klicken zum Installieren";}else{UpdatesButton.Content="UPDATES · "+(result.Latest is null?"OFFLINE":"AKTUELL");UpdatesButton.ToolTip=result.Message;}}
 void RegisterInsertHotkey(object? sender,EventArgs e){var h=new WindowInteropHelper(this).Handle;var source=HwndSource.FromHwnd(h);source.AddHook(WindowMessage);if(NativeMethods.RegisterHotKey(h,HotkeyId,0,0x2D))Append("INSERT registriert (Windows-Hotkey, kein Input-Hook).");else Append("INSERT konnte nicht global registriert werden; Umschalten bleibt in der App möglich.");}
 IntPtr WindowMessage(IntPtr hwnd,int msg,IntPtr wParam,IntPtr lParam,ref bool handled){if(msg==WmHotkey&&wParam.ToInt32()==HotkeyId){ToggleOverlay();handled=true;}return IntPtr.Zero;}
 void OnKey(object s,KeyEventArgs e){if(e.Key==Key.Insert){ToggleOverlay();e.Handled=true;}}
 void ToggleOverlay(){if(overlay.IsVisible){overlay.Hide();OverlayState.Text="Aus · INSERT";}else{overlay.Show();OverlayState.Text="An · INSERT";}}
